"""Join four original CARLA RGB callbacks to 900 world ticks and seal PNGs.

The caller owns sensor placement and must separately review sign visibility.
This module never substitutes generated pixels for Native callback data.
"""
from __future__ import annotations

import hashlib
import io
import json
import math
import queue
from pathlib import Path
from zipfile import ZIP_STORED, ZipFile

from PIL import Image


DIMENSIONS = {"front": (1920, 1080), "rear": (1280, 720),
              "left": (1280, 720), "right": (1280, 720)}


def _png(image, dimensions):
    width, height = dimensions
    if (image.width, image.height) != (width, height):
        raise ValueError("original camera dimensions mismatch")
    raw = bytes(image.raw_data)
    if len(raw) != width * height * 4:
        raise ValueError("original camera BGRA byte count mismatch")
    output = io.BytesIO()
    Image.frombytes("RGB", (width, height), raw, "raw", "BGRX").save(output, format="PNG")
    return output.getvalue()


class NativeCameraWriter:
    def __init__(self, sensors, output_root, dimensions=None):
        self.dimensions = DIMENSIONS if dimensions is None else dimensions
        if set(sensors) != set(DIMENSIONS) or set(self.dimensions) != set(DIMENSIONS):
            raise ValueError("four named original RGB cameras required")
        self.root = Path(output_root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.queues = {name: queue.Queue(maxsize=4) for name in DIMENSIONS}
        self.archives = {}
        self.last_frame = None
        self.first_frame = None
        self.count = 0
        for name, sensor in sensors.items():
            if getattr(sensor, "type_id", None) != "sensor.camera.rgb":
                raise ValueError("original RGB sensor required")
            attrs = sensor.attributes
            width, height = self.dimensions[name]
            if (str(attrs.get("image_size_x")), str(attrs.get("image_size_y"))) != (str(width), str(height)):
                raise ValueError("sensor profile differs")
            self.archives[name] = ZipFile(self.root / (name + ".png.zip"), "w", compression=ZIP_STORED)
            sensor.listen(self.queues[name].put)

    def capture(self, snapshot):
        frame = snapshot.frame
        stamp = snapshot.timestamp.elapsed_seconds
        if not isinstance(frame, int) or not math.isfinite(stamp):
            raise ValueError("original world frame and timestamp required")
        if self.last_frame is not None and frame != self.last_frame + 1:
            raise ValueError("world frame sequence mismatch")
        if self.count >= 900:
            raise ValueError("900-frame capture exceeded")
        bindings = {}
        for name in DIMENSIONS:
            image = self.queues[name].get(timeout=5)
            if image.frame != frame or abs(image.timestamp - stamp) > 0.001:
                raise ValueError("camera callback frame or timestamp mismatch")
            payload = _png(image, self.dimensions[name])
            member = f"{frame:08d}.png"
            self.archives[name].writestr(member, payload)
            bindings[name] = {"member": member, "sha256": hashlib.sha256(payload).hexdigest()}
        self.first_frame = frame if self.first_frame is None else self.first_frame
        self.last_frame = frame
        self.count += 1
        return bindings

    def close(self):
        for archive in self.archives.values():
            archive.close()
        if self.count != 900:
            raise ValueError("original 900-frame capture incomplete")
        refs = {}
        for name in DIMENSIONS:
            path = self.root / (name + ".png.zip")
            refs[name] = {"path": path.name, "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                          "frame_count": 900, "fps": 20, "dimensions": list(self.dimensions[name])}
        return refs


def seal_rows(root, rows, camera_refs):
    """Write exact frame-map and actor-row hashes after 900 complete ticks."""
    root = Path(root)
    if len(rows) != 900 or set(camera_refs) != set(DIMENSIONS):
        raise ValueError("incomplete original capture")
    mapping = [{"frame": row["frame"], "time_s": row["time_s"]} for row in rows]
    refs = {}
    for name, value in (("actor_rows", rows), ("frame_map", mapping)):
        path = root / (name + ".json")
        path.write_text(json.dumps(value, separators=(",", ":")) + "\n")
        refs[name] = {"path": path.name, "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
    return {**refs, "camera_archives": camera_refs, "cameras": camera_refs}

import hashlib
import importlib.util
import unittest
from pathlib import Path
from types import SimpleNamespace as NS


FOLDER = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("native_carla_adapter", FOLDER / "native_carla_adapter.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


class Map:
    name = "ReviewedMap"

    def to_opendrive(self):
        return "original-map"

    def get_waypoint(self, location, project_to_road=False):
        assert not project_to_road
        return NS(transform=NS(location=location))


class Actor:
    id = 12

    def set_autopilot(self, value):
        self.autopilot = value

    def get_transform(self):
        return NS(location=NS(x=0.0, y=0.0))

    def get_velocity(self):
        return NS(length=lambda: 0.0)

    def apply_control(self, value):
        self.control = value


class World:
    def __init__(self):
        self.actor = Actor()

    def get_map(self):
        return Map()

    def get_environment_objects(self):
        return [NS(id=41, name="reviewed-sign")]

    def get_blueprint_library(self):
        return NS(find=lambda name: NS(id=name))

    def try_spawn_actor(self, blueprint, transform):
        return self.actor


class NativeAdapterTests(unittest.TestCase):
    def setUp(self):
        self.world = World()
        self.api = NS(Location=lambda **kw: NS(**kw), VehicleControl=lambda **kw: kw)
        self.adapter = module.NativeParkingAdapter(self.world, self.api)
        self.site = {"map_name": "ReviewedMap", "approach_waypoints": [[0, 0], [2, 0]],
                     "parking_polygon": [[0, 0], [3, 0], [3, 3]],
                     "native_opendrive_sha256": hashlib.sha256(b"original-map").hexdigest()}
        self.device = {"native_object_id": 41, "native_object_name": "reviewed-sign",
                       "instruction_review_sha256": "1" * 64, "authority_review_sha256": "2" * 64,
                       "device_id": "sign", "exact_instruction": "NO PARKING",
                       "governed_polygon": self.site["parking_polygon"]}

    def test_reviewed_map_sign_and_vehicle_drive_request(self):
        self.assertEqual(self.adapter.verify_site(self.site)["map_name"], "ReviewedMap")
        self.assertEqual(self.adapter.install_and_read_device(self.device)["exact_instruction"], "NO PARKING")
        self.adapter.configure_effective_window("sign", "effective", [[0, 100]])
        self.assertTrue(self.adapter.read_device_effective("sign"))
        vehicle = self.adapter.spawn_driver_vehicle({"blueprint": "vehicle.test"}, [0, 0])
        self.adapter.configure_parking_route(vehicle["actor_id"], [[0, 0], [2, 0]], self.site["parking_polygon"], "park")
        self.adapter.configure_exception_cause(vehicle["actor_id"], "none")
        self.adapter.control_step()
        self.assertGreater(self.world.actor.control["throttle"], 0)

    def test_unreviewed_map_rejected(self):
        self.site["native_opendrive_sha256"] = "0" * 64
        with self.assertRaisesRegex(ValueError, "map digest"):
            self.adapter.verify_site(self.site)

    def test_unreviewed_sign_rejected(self):
        self.device.pop("authority_review_sha256")
        with self.assertRaisesRegex(ValueError, "reviews required"):
            self.adapter.install_and_read_device(self.device)

    def test_exception_requires_source(self):
        vehicle = self.adapter.spawn_driver_vehicle({"blueprint": "vehicle.test"}, [0, 0])
        with self.assertRaisesRegex(ValueError, "exception cause packet"):
            self.adapter.configure_exception_cause(vehicle["actor_id"], "police_direction")


if __name__ == "__main__":
    unittest.main()

import importlib.util
import tempfile
import unittest
from pathlib import Path
from types import SimpleNamespace


FOLDER = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("native_camera_writer", FOLDER / "native_camera_writer.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


class Sensor:
    type_id = "sensor.camera.rgb"
    attributes = {"image_size_x": "2", "image_size_y": "2"}

    def listen(self, callback):
        self.callback = callback


class WriterTests(unittest.TestCase):
    def setUp(self):
        scratch = FOLDER.parents[1] / ".runtime-work" / "c229439-camera-tests"
        scratch.mkdir(parents=True, exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=scratch)
        self.sensors = {key: Sensor() for key in module.DIMENSIONS}
        dims = {key: (2, 2) for key in module.DIMENSIONS}
        self.writer = module.NativeCameraWriter(self.sensors, self.temp.name, dims)

    def tearDown(self):
        for archive in self.writer.archives.values():
            archive.close()
        self.temp.cleanup()

    def tick(self, frame, bad_camera=None):
        stamp = frame * 0.05
        for name, sensor in self.sensors.items():
            camera_frame = frame + 1 if name == bad_camera else frame
            sensor.callback(SimpleNamespace(frame=camera_frame, timestamp=stamp,
                                            width=2, height=2, raw_data=bytes(16)))
        return self.writer.capture(SimpleNamespace(frame=frame,
                                                    timestamp=SimpleNamespace(elapsed_seconds=stamp)))

    def test_complete_original_archives_and_row_bindings(self):
        rows = []
        for frame in range(900):
            bindings = self.tick(frame)
            rows.append({"frame": frame, "time_s": frame * 0.05, "camera_frames": bindings})
        refs = self.writer.close()
        self.assertEqual(refs["front"]["frame_count"], 900)
        sealed = module.seal_rows(self.temp.name, rows, refs)
        self.assertEqual(set(sealed["camera_archives"]), set(module.DIMENSIONS))

    def test_wrong_callback_frame_rejected(self):
        with self.assertRaisesRegex(ValueError, "camera callback frame"):
            self.tick(0, "left")

    def test_missing_frames_rejected_on_close(self):
        self.tick(0)
        with self.assertRaisesRegex(ValueError, "900-frame capture incomplete"):
            self.writer.close()


if __name__ == "__main__":
    unittest.main()
